mapper.select:
SELECT DISTINCT EXISTS(SELECT 1 FROM mail_star ms WHERE ms.user_id=#{userId} AND ms.mail_id=m.mail_id) is_starred,m.mail_id, m.sender_id, u.username sender_name,u.email sender_email,m.subject, LEFT(m.content,50) content, m.send_time,
                m.has_attachment, m.is_spam, m.priority, m.mail_status, m.sender_deleted
FROM mail m JOIN user u ON u.user_id=m.sender_id
LEFT JOIN mail_receiver mr
       ON mr.mail_id = m.mail_id
      AND mr.receiver_id = #{userId}

WHERE m.mail_status=1

  AND ((m.sender_id=#{userId} AND m.sender_deleted=TRUE) OR mr.is_deleted=TRUE)
  AND m.sender_id=#{userId} AND m.sender_deleted=FALSE
  AND mr.receiver_id=#{userId} AND mr.is_deleted=FALSE
    AND m.is_spam=TRUEAND m.is_spam=FALSE

  AND 
    AND EXISTS(SELECT 1 FROM mail_star s WHERE s.mail_id=m.mail_id AND s.user_id=#{userId})



  AND mr.is_read = #{isRead}


  AND m.has_attachment = #{hasAttachment}


  AND m.send_time >= #{startTime}


  AND m.send_time <= #{endTime}

AND (m.send_time < #{time} OR (m.send_time=#{time} AND m.mail_id < #{id}))
ORDER BY m.send_time DESC,m.mail_id DESC LIMIT #{limit}
